-- RC-773, RC-774, RC-778 (RP-138): who called an MCP server, derived at OTLP ingest by
-- ingest/otlp/dimensions/client.ts, on MCP server spans only: the harness (normalized id), the raw
-- client name or User-Agent product it came from, its version, how it was found (sdk | semconv |
-- heuristic), the ISO country of the caller's IP (from the local DB-IP IP-to-Country Lite file,
-- ingest/otlp/dimensions/geo.ts), the transport (stdio | http) and the MCP protocol version. No
-- column keeps the caller's IP: ingest reads its country and drops it (the owner's decision, in
-- place of upstream's admin-only client_ip). The trace rollup gets the callers' countries and
-- harnesses, for the Traces country and harness filters.
-- Generated by drizzle-kit from ingest/otlp/schema.ts and synthesis/traces/schema.ts, then written
-- as upstream's 0111, 0112 and 0113 (ratel-cloud): IF NOT EXISTS, so a database migrated by
-- ratel-cloud already has them and this is a no-op there. Nullable or constant-default columns:
-- the ALTERs change the catalog only and rewrite no row. Rows stored before this stay null / '{}'.
-- On large databases, build the indexes first out of band, outside a transaction (psql autocommit),
-- after the ALTERs:
--   CREATE INDEX CONCURRENTLY IF NOT EXISTS "otel_spans_project_mcp_session_idx" ON "otel_spans" USING btree ("project_id","mcp_session_id") WHERE "otel_spans"."mcp_session_id" is not null;
--   CREATE INDEX CONCURRENTLY IF NOT EXISTS "otel_trace_summaries_countries_idx" ON "otel_trace_summaries" USING gin ("countries");
--   CREATE INDEX CONCURRENTLY IF NOT EXISTS "otel_trace_summaries_harnesses_idx" ON "otel_trace_summaries" USING gin ("harnesses");
-- Then the IF NOT EXISTS statements here are no-ops at deploy.
ALTER TABLE "otel_spans" ADD COLUMN IF NOT EXISTS "harness" text;--> statement-breakpoint
ALTER TABLE "otel_spans" ADD COLUMN IF NOT EXISTS "harness_raw" text;--> statement-breakpoint
ALTER TABLE "otel_spans" ADD COLUMN IF NOT EXISTS "harness_version" text;--> statement-breakpoint
ALTER TABLE "otel_spans" ADD COLUMN IF NOT EXISTS "harness_source" text;--> statement-breakpoint
ALTER TABLE "otel_spans" ADD COLUMN IF NOT EXISTS "geo_country" text;--> statement-breakpoint
ALTER TABLE "otel_spans" ADD COLUMN IF NOT EXISTS "mcp_transport" text;--> statement-breakpoint
ALTER TABLE "otel_spans" ADD COLUMN IF NOT EXISTS "mcp_protocol_version" text;--> statement-breakpoint
ALTER TABLE "otel_trace_summaries" ADD COLUMN IF NOT EXISTS "countries" text[] DEFAULT '{}'::text[] NOT NULL;--> statement-breakpoint
ALTER TABLE "otel_trace_summaries" ADD COLUMN IF NOT EXISTS "harnesses" text[] DEFAULT '{}'::text[] NOT NULL;--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "otel_spans_project_mcp_session_idx" ON "otel_spans" USING btree ("project_id","mcp_session_id") WHERE "otel_spans"."mcp_session_id" is not null;--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "otel_trace_summaries_countries_idx" ON "otel_trace_summaries" USING gin ("countries");--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "otel_trace_summaries_harnesses_idx" ON "otel_trace_summaries" USING gin ("harnesses");
